insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000500011','40000000-0000-4000-8000-000000050001','O deslocamento deve ser somado à posição inicial para produzir a final.',1),('60000000-0000-4000-8000-000000500012','40000000-0000-4000-8000-000000050001','Escreva $\overrightarrow{AB}=B-A$.',2),('60000000-0000-4000-8000-000000500013','40000000-0000-4000-8000-000000050001','Confira se $A+\overrightarrow{AB}$ devolve $B$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050001','$\overrightarrow{AB}=(-3,5,2)$.','Um deslocamento orientado depende da ordem dos pontos. Subtrair a posição inicial da final registra a variação em cada eixo e evita inverter o sentido.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000500011','40000000-0000-4000-8000-000000050001','Fixe a orientação','O vetor pedido parte de $A$ e chega a $B$.',1),('70000000-0000-4000-8000-000000500012','40000000-0000-4000-8000-000000050001','Subtraia as coordenadas','$(-1-2,4-(-1),5-3)=(-3,5,2)$.',2),('70000000-0000-4000-8000-000000500013','40000000-0000-4000-8000-000000050001','Teste a recomposição','$(2,-1,3)+(-3,5,2)=(-1,4,5)$.',3),('70000000-0000-4000-8000-000000500014','40000000-0000-4000-8000-000000050001','Conclua','A alternativa A tem o sentido e as componentes corretos.',4) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
