insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000500021','40000000-0000-4000-8000-000000050002','Um vetor é uma classe de segmentos orientados equipolentes.',1),('60000000-0000-4000-8000-000000500022','40000000-0000-4000-8000-000000050002','A posição do segmento não faz parte das características do vetor.',2),('60000000-0000-4000-8000-000000500023','40000000-0000-4000-8000-000000050002','Compare direção, sentido e módulo.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050002','Eles representam o mesmo vetor.','Vetores livres não ficam presos ao ponto onde foram desenhados. Segmentos com direção, sentido e comprimento iguais são representantes do mesmo vetor, mesmo em retas paralelas distintas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000500021','40000000-0000-4000-8000-000000050002','Liste os dados','As três propriedades que caracterizam um vetor coincidem.',1),('70000000-0000-4000-8000-000000500022','40000000-0000-4000-8000-000000050002','Use a definição','Segmentos com essas propriedades são equipolentes.',2),('70000000-0000-4000-8000-000000500023','40000000-0000-4000-8000-000000050002','Separe posição de vetor','Origem e extremidade podem mudar sem mudar o vetor.',3),('70000000-0000-4000-8000-000000500024','40000000-0000-4000-8000-000000050002','Conclua','Somente a alternativa A expressa essa equivalência.',4) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
