insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050003','$Q=(1,1,1)$.','Aplicar um vetor em um ponto é fazer uma translação. Cada componente de $v$ informa quanto a coordenada correspondente de $P$ deve variar.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000500031','40000000-0000-4000-8000-000000050003','Escreva a translação','$Q=P+v$.',1),('70000000-0000-4000-8000-000000500032','40000000-0000-4000-8000-000000050003','Some a primeira coordenada','$5+(-4)=1$.',2),('70000000-0000-4000-8000-000000500033','40000000-0000-4000-8000-000000050003','Complete as demais','$-2+3=1$ e $0+1=1$.',3),('70000000-0000-4000-8000-000000500034','40000000-0000-4000-8000-000000050003','Verifique','$Q-P=(-4,3,1)$, como exigido.',4) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
