insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050004','$(-4,6,-2)$.','A colinearidade exige proporcionalidade global, não apenas sinais parecidos. Multiplicar $u$ por $-2$ preserva a direção da reta e inverte o sentido.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
