insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000500061','40000000-0000-4000-8000-000000050006','Use $M=(A+B)/2$.',1),('60000000-0000-4000-8000-000000500062','40000000-0000-4000-8000-000000050006','Isole $B$ antes de substituir as coordenadas.',2),('60000000-0000-4000-8000-000000500063','40000000-0000-4000-8000-000000050006','A resposta deve deixar $M$ exatamente no meio de $A$ e $B$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050006','$B=(4,1,-8)$.','O ponto médio é a média componente a componente. Recuperar uma extremidade exige desfazer essa média, isto é, dobrar o ponto médio e subtrair a extremidade conhecida.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000500061','40000000-0000-4000-8000-000000050006','Isole a incógnita','$B=2M-A$.',1),('70000000-0000-4000-8000-000000500062','40000000-0000-4000-8000-000000050006','Dobre o ponto médio','$2M=(2,6,-4)$.',2),('70000000-0000-4000-8000-000000500063','40000000-0000-4000-8000-000000050006','Subtraia A','$(2,6,-4)-(-2,5,4)=(4,1,-8)$.',3),('70000000-0000-4000-8000-000000500064','40000000-0000-4000-8000-000000050006','Confira','A média de $A$ e $B$ é $(1,3,-2)$.',4) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
