insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000500071','40000000-0000-4000-8000-000000050007','O deslocamento total independe do caminho intermediário.',1),('60000000-0000-4000-8000-000000500072','40000000-0000-4000-8000-000000050007','Você pode calcular $C-A$ ou somar $\overrightarrow{AB}$ e $\overrightarrow{BC}$.',2),('60000000-0000-4000-8000-000000500073','40000000-0000-4000-8000-000000050007','Compare o resultado com a mudança de cada coordenada entre A e C.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050007','$\overrightarrow{AC}=(1,5,5)$.','Deslocamentos se compõem pela regra do triângulo. O ponto intermediário cancela ao somar os dois vetores, deixando apenas a diferença entre chegada e partida.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
