insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050008','A coordenada y permanece constante durante a translação.','A segunda coordenada vale $4$ nos dois pontos, então a componente y do deslocamento é zero. Ainda há variações em x e z; portanto o vetor não é nulo nem paralelo ao eixo y.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
