insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050015','A terceira componente deve ser $-3$.','O erro está na subtração da terceira coordenada. Como o ponto final tem z menor, o deslocamento nessa direção precisa ser negativo.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
