insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000500161','40000000-0000-4000-8000-000000050016','Componentes nulas não geram movimento nos respectivos eixos.',1),('60000000-0000-4000-8000-000000500162','40000000-0000-4000-8000-000000050016','O sinal da componente não nula define o sentido.',2),('60000000-0000-4000-8000-000000500163','40000000-0000-4000-8000-000000050016','O módulo é 6, mas a direção é y.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000050016','Seis unidades no sentido negativo de y.','O vetor tem apenas a segunda componente diferente de zero. Por isso o movimento fica restrito ao eixo y e seu sinal negativo aponta no sentido decrescente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
